use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut i = 0
            while i < ks.len() {
                if ks[i] == k {
                    ks.remove(i)
                    vs.remove(i)
                    break
                }
                i += 1
            }
            ks.push(k)
            vs.push(v)
            if ks.len() as int > cap {
                println("evict ${ks[0]}")
                ks.remove(0)
                vs.remove(0)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = false
            let mut i = 0
            while i < ks.len() {
                if ks[i] == k {
                    let v = vs[i]
                    ks.remove(i)
                    vs.remove(i)
                    ks.push(k)
                    vs.push(v)
                    println("${v}")
                    found = true
                    break
                }
                i += 1
            }
            if !found {
                println("-1")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = ks.len()
                while i > 0 {
                    i -= 1
                    if out != "" {
                        out = "${out} "
                    }
                    out = "${out}${ks[i]}"
                }
                println(out)
            }
        }
    }
}

